begin;
-- Synthetic identities only; no real passwords or emails; all changes rolled back.
insert into auth.users(id,email) select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'fixture'||n||'@example.invalid' from generate_series(1,7)n;
insert into auth.sessions(id,user_id) select ('10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from generate_series(1,7)n;
insert into public.organizations(id,name) values('20000000-0000-4000-8000-000000000001','Test other organization');
insert into public.profiles(id,organization_id,username,full_name,role,active) select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=7 then '20000000-0000-4000-8000-000000000001'::uuid else '6e143c55-7be5-4e6e-9f1a-8f8db429956a'::uuid end,'rls_fixture_'||n,'Synthetic fixture '||n,case n when 1 then 'admin' when 2 then 'teacher' when 3 then 'student' when 4 then 'student' when 5 then 'supervisor' when 6 then 'teacher' else 'admin' end,n<>6 from generate_series(1,7)n;
insert into public.classes(id,organization_id,name) values('30000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','Fixture 7A'),('30000000-0000-4000-8000-000000000002','6e143c55-7be5-4e6e-9f1a-8f8db429956a','Fixture 7A1'),('30000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','Fixture Other');
insert into public.subjects(id,organization_id,name) values('40000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','Fixture IPS');
insert into public.teacher_assignments(organization_id,teacher_id,class_id,subject_id) values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','00000000-0000-4000-8000-000000000002','30000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001');
insert into public.student_enrollments(organization_id,student_id,class_id) values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','00000000-0000-4000-8000-000000000003','30000000-0000-4000-8000-000000000001'),('6e143c55-7be5-4e6e-9f1a-8f8db429956a','00000000-0000-4000-8000-000000000004','30000000-0000-4000-8000-000000000002');
create function pg_temp.assert_true(ok boolean, label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'Assertion failed: %',label; end if; end $$;
insert into public.exams(id,organization_id,subject_id,title,starts_at,ends_at,duration_minutes,pin_hash) values('50000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','40000000-0000-4000-8000-000000000001','Synthetic exam',now(),now()+interval '1 hour',60,'synthetic-only');
insert into public.exam_rooms(id,organization_id,exam_id,name,capacity) values('60000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','50000000-0000-4000-8000-000000000001','Synthetic room 1',1),('60000000-0000-4000-8000-000000000002','6e143c55-7be5-4e6e-9f1a-8f8db429956a','50000000-0000-4000-8000-000000000001','Synthetic room 2',2);
insert into public.supervisor_assignments(id,organization_id,exam_id,room_id,original_supervisor_id) values('70000000-0000-4000-8000-000000000001','6e143c55-7be5-4e6e-9f1a-8f8db429956a','50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002');
insert into public.supervisor_substitutions(assignment_id,substitute_supervisor_id) values('70000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000005');
insert into public.exam_room_students values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003');
do $$ declare denied boolean=false;begin begin insert into public.exam_room_students values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000004');exception when raise_exception then denied=true;end;perform pg_temp.assert_true(denied,'Capacity enforced');end $$;
do $$ declare denied boolean=false;begin begin insert into public.exam_room_students values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','50000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003');exception when unique_violation then denied=true;end;perform pg_temp.assert_true(denied,'One room per student per exam');end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=2 from public.classes),'Admin limited to own organization');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=1 from public.classes),'Teacher exact class, not substring');
select pg_temp.assert_true(not public.has_supervisor_context(),'Original supervisor loses access during substitution');
select pg_temp.assert_true((select count(*)=1 from public.profiles where role='student'),'Teacher sees assigned students only');
do $$ begin begin insert into public.classes(organization_id,name) values('6e143c55-7be5-4e6e-9f1a-8f8db429956a','Forbidden');raise exception 'Teacher write unexpectedly allowed';exception when insufficient_privilege then null;end;end $$;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","session_id":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=1 from public.profiles),'Student sees self only');
select pg_temp.assert_true(not public.has_supervisor_context(),'Student cannot use supervisor context');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000006","session_id":"10000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=0 from public.profiles),'Inactive actor rejected');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","session_id":"99999999-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=0 from public.profiles),'Revoked or forged session rejected');
set local role anon;
do $$ begin begin perform * from public.profiles;raise exception 'Anonymous read unexpectedly allowed';exception when insufficient_privilege then null;end;end $$;
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000005","session_id":"10000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select pg_temp.assert_true(public.has_supervisor_context(),'Active substitute authorized');
reset role;
update public.supervisor_substitutions set revoked_at=now() where assignment_id='70000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert_true(public.has_supervisor_context(),'Original supervisor restored');
do $$ begin begin perform * from public.question_versions;raise exception 'Question keys unexpectedly readable';exception when insufficient_privilege then null;end;end $$;
reset role;
select pg_temp.assert_true(not (select public from storage.buckets where id='exam-media'),'Media bucket private');
select pg_temp.assert_true((select count(*)=21 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity),'RLS enabled on all 21 application tables');
rollback;
